export const TERMINAL_SETUP_COMMANDS = "# ==============================================================================\n# TERMINAL SETUP COMMANDS (STREAMLIT.APP DEPLOYMENT READY)\n# ==============================================================================\n\n# 1. Initialize Git repository\ngit init\n\n# 2. Setup virtual environment\npython3 -m venv venv\nsource venv/bin/activate  # Windows: venv\\Scripts\\activate\n\n# 3. Install packages (includes excel, pdf, doc generators)\npip install streamlit supabase pandas openpyxl reportlab python-docx\n\n# 4. Create secrets directory and secrets file\nmkdir -p .streamlit\ntouch .streamlit/secrets.toml\n\n# 5. Protect secrets with .gitignore\necho \".streamlit/secrets.toml\" > .gitignore\necho \"venv/\" >> .gitignore\necho \"__pycache__/\" >> .gitignore\necho \".env\" >> .gitignore\n\n# 6. Test locally\nstreamlit run app.py\n\n# 7. Push to GitHub to deploy on streamlit.app (Streamlit Community Cloud)\ngit add .\ngit commit -m \"Deploy inventory suite with shipment equal dispersion, 5% profit tab, printing and exports\"\ngit branch -M main\ngit remote add origin https://github.com/YOUR_USERNAME/YOUR_REPOSITORY.git\ngit push -u origin main\n";
